<?php
require_once __DIR__.'/sales.php';
$kind=is_string($_GET['period']??null)?$_GET['period']:'month';$date=is_string($_GET['date']??null)?$_GET['date']:date('Y-m-d');
try{$range=salesPeriod($kind,$date);}catch(InvalidArgumentException $e){echo '<div class="alert error">'.e($e->getMessage()).'</div>';return;}
$s=salesTotals($range['start'],$range['end']);$previous=salesTotals($range['previous_start'],$range['previous_end']);$receipts=salesReceipts($range['start'],$range['end']);$products=salesProducts($range['start'],$range['end']);$delta=$s['kimchi']-$previous['kimchi'];
$unknown=query('SELECT COUNT(*) count,COALESCE(SUM(p.amount_cents),0) amount FROM payments p JOIN orders o ON o.id=p.order_id WHERE o.cancelled=0 AND p.paid_on IS NULL AND o.order_date BETWEEN ? AND ?',[$range['start'],$range['end']])->fetch();
?>
<section class="panel"><form method="get" class="inline-form"><input type="hidden" name="page" value="sales"><label>보고 싶은 기간<select name="period"><?php foreach(['week'=>'주간','month'=>'월간','year'=>'연간'] as $key=>$label): ?><option value="<?=$key?>" <?=$kind===$key?'selected':''?>><?=$label?></option><?php endforeach ?></select></label><label>기준 날짜<input type="date" name="date" value="<?=e($date)?>" required></label><button class="button">통계 보기</button></form><p><strong><?=e($range['start'])?> ~ <?=e($range['end'])?></strong> · 주문 날짜 기준 · CAD</p><p class="hint">취소 주문·취소 수량을 제외하고 할인 후 금액을 표시합니다. 아직 전달·입금하지 않은 주문도 포함하므로 실제 입금액과 다를 수 있습니다.</p></section>
<div class="stats"><article><p>김치 판매액</p><strong><?=money($s['kimchi'])?></strong><span>할인 후 · 배달비 제외</span></article><article><p>주문 수</p><strong><?=$s['order_count']?><small>건</small></strong><span>고객 <?=$s['customer_count']?>명</span></article><article><p>전체 주문 금액</p><strong><?=money($s['total'])?></strong><span>배달비·기타 판매 포함</span></article><article class="warm"><p>이 기간 주문의 미입금</p><strong><?=money($s['unpaid'])?></strong><span>현재 남은 금액 기준</span></article></div>
<section class="panel"><h2>매출과 추가 수입 구분</h2><div class="table-wrap"><table><tbody><?php foreach(['kimchi'=>'김치 판매액','delivery'=>'배달비','other_sales'=>'기타 판매 (김밥 등)','other_charges'=>'기타 청구','additional_income'=>'동의받은 추가 수입'] as $key=>$label): ?><tr><th><?=$label?></th><td><?=money($s[$key])?></td></tr><?php endforeach ?></tbody></table></div><p class="hint">추가 수입은 주문 청구액·김치 판매액에 다시 더하지 않습니다. 고객 예치금으로 처리하지 않습니다.</p></section>
<section class="panel"><h2>전년도와 비교하기</h2><p>비교 기간 <?=e($range['previous_start'])?> ~ <?=e($range['previous_end'])?><?=$kind==='week'?' · 같은 요일의 52주 전':''?></p><div class="table-wrap"><table><thead><tr><th>항목</th><th>선택 기간</th><th>전년도 비교 기간</th></tr></thead><tbody><tr><th>김치 판매액</th><td><?=money($s['kimchi'])?></td><td><?=money($previous['kimchi'])?></td></tr><tr><th>주문 수</th><td><?=$s['order_count']?>건</td><td><?=$previous['order_count']?>건</td></tr></tbody></table></div><p>김치 판매액 차이 <?=($delta<0?'−':'+').money(abs($delta))?> · <?=$previous['kimchi']>0?number_format($delta/$previous['kimchi']*100,1).'%':'전년도 금액이 없어 증감률 계산 불가'?></p><p class="hint">진행 중인 주·월·연도는 완료된 전년도 기간보다 작게 보일 수 있습니다. 전년도 자료가 없는 경우 0은 확인된 무매출을 뜻하지 않습니다. 과거 실적은 주문 예상의 참고 자료이며 자동 생산 확정 수량이 아닙니다.</p></section>
<section class="panel"><h2>제품별 판매</h2><?php if(!$products): ?><p>이 기간에 등록된 제품 주문이 없습니다.</p><?php else: ?><div class="table-wrap"><table><thead><tr><th>제품</th><th>용량</th><th>판매 수량</th><th>할인 후 판매액</th></tr></thead><tbody><?php foreach($products as $p): ?><tr><td><?=e($p['product_name'])?></td><td><?=weight($p['weight_g'])?></td><td><?=(int)$p['quantity']?>개</td><td><?=money((int)$p['amount'])?></td></tr><?php endforeach ?></tbody></table></div><p class="hint">같은 제품도 과거 용량이 다르면 구분합니다. 배달비·기타 판매·추가 수입은 제품 판매액에서 제외합니다.</p><?php endif ?></section>
<section class="panel"><h2>실제 입금일 기준</h2><p>입금일이 <?=e($range['start'])?> ~ <?=e($range['end'])?>인 기록: <strong><?=money($receipts['amount'])?></strong> · <?=$receipts['receipt_count']?>회</p><p>이 중 별도 추가 수입 <?=money($receipts['additional_income'])?></p><p class="hint">다른 기간에 주문한 제품의 입금도 포함합니다. 주문일 기준 위 통계와 합산하지 않습니다.</p><?php if($unknown['count']): ?><div class="notice">선택 기간에 주문한 과거 입금 중 날짜 미기록 <?=(int)$unknown['count']?>회 · <?=money((int)$unknown['amount'])?>가 있습니다. 실제 입금일을 알 수 없어 입금일 기준 통계에서는 제외했습니다.</div><?php endif ?></section>
